  'Find answers to common questions about AajExam platform, subscriptions, and exam preparation': 'AajExam ପ୍ଲାଟଫର୍ମ, ସବ୍‌ସ୍କ୍ରିପସନ୍ ଓ ପରୀକ୍ଷା ପ୍ରସ୍ତୁତି ବିଷୟରେ ସାଧାରଣ ପ୍ରଶ୍ନର ଉତ୍ତର ଖୋଜନ୍ତୁ',
  'First, try clearing your browser cache and cookies, or try a different browser. If issues persist, contact our support team at {email} with details about the problem, your device, and browser information.': 'ପ୍ରଥମେ ଆପଣଙ୍କ ବ୍ରାଉଜରର କ୍ୟାସ୍ ଓ କୁକିଜ୍ ସଫା କରନ୍ତୁ ବା ଅନ୍ୟ ବ୍ରାଉଜର୍ ଚେଷ୍ଟା କରନ୍ତୁ। ସମସ୍ୟା ରହିଲେ, ସମସ୍ୟା, ଆପଣଙ୍କ ଡିଭାଇସ୍ ଓ ବ୍ରାଉଜର୍ ବିବରଣୀ ସହ ଆମ ସପୋର୍ଟ ଟିମ୍‌କୁ {email} ରେ ଯୋଗାଯୋଗ କରନ୍ତୁ।',
