  'Join thousands of students who are already passing exams and earning cash by referring friends to AajExam.': 'ପୂର୍ବରୁ ପରୀକ୍ଷାରେ ପାସ୍ କରୁଥିବା ଓ AajExam ରେ ବନ୍ଧୁମାନଙ୍କୁ ରେଫର୍ କରି ଟଙ୍କା ଆୟ କରୁଥିବା ହଜାର ହଜାର ଛାତ୍ରଛାତ୍ରୀଙ୍କ ସହ ଯୋଗ ଦିଅନ୍ତୁ।',
