  'Thousands of students are already studying, scoring better, and earning by inviting friends. Join them today.': 'ହଜାର ହଜାର ଛାତ୍ରଛାତ୍ରୀ ପୂର୍ବରୁ ପଢ଼ୁଛନ୍ତି, ଭଲ ସ୍କୋର୍ କରୁଛନ୍ତି ଓ ବନ୍ଧୁମାନଙ୍କୁ ନିମନ୍ତ୍ରଣ କରି ଆୟ କରୁଛନ୍ତି। ଆଜି ହିଁ ସେମାନଙ୍କ ସହ ଯୋଗ ଦିଅନ୍ତୁ।',
  'To become India\'s most trusted and comprehensive government exam preparation platform, empowering millions of students to achieve their career goals in public service through innovative technology and quality educational content.': 'ନବୀନ ପ୍ରଯୁକ୍ତି ଓ ମାନସମ୍ମତ ଶିକ୍ଷାମୂଳକ ବିଷୟବସ୍ତୁ ମାଧ୍ୟମରେ ଲକ୍ଷ ଲକ୍ଷ ଛାତ୍ରଛାତ୍ରୀଙ୍କୁ ଜନସେବାରେ ନିଜ କ୍ୟାରିଅର୍ ଲକ୍ଷ୍ୟ ହାସଲ କରିବାକୁ ସକ୍ଷମ କରି, ଭାରତର ସବୁଠାରୁ ବିଶ୍ୱସନୀୟ ଓ ବ୍ୟାପକ ସରକାରୀ ପରୀକ୍ଷା ପ୍ରସ୍ତୁତି ପ୍ଲାଟଫର୍ମ ହେବା।',
  'To provide accessible, affordable, and effective exam preparation resources that combine cutting-edge technology with proven pedagogical methods. We aim to bridge the gap between traditional coaching and modern digital learning.': 'ଅତ୍ୟାଧୁନିକ ପ୍ରଯୁକ୍ତିକୁ ପ୍ରମାଣିତ ଶିକ୍ଷଣ ପଦ୍ଧତି ସହ ମିଶାଉଥିବା ସୁଲଭ, ସୁଲଭମୂଲ୍ୟର ଓ ପ୍ରଭାବଶାଳୀ ପରୀକ୍ଷା ପ୍ରସ୍ତୁତି ସମ୍ବଳ ଯୋଗାଇବା। ପାରମ୍ପରିକ କୋଚିଂ ଓ ଆଧୁନିକ ଡିଜିଟାଲ୍ ଶିକ୍ଷା ମଧ୍ୟରେ ବ୍ୟବଧାନ ପୂରଣ କରିବା ଆମର ଲକ୍ଷ୍ୟ।',
