  'Invite your friends to AajExam and earn cash rewards when they upgrade to PRO.': 'ଆପଣଙ୍କ ବନ୍ଧୁମାନଙ୍କୁ AajExam କୁ ନିମନ୍ତ୍ରଣ କରନ୍ତୁ ଓ ସେମାନେ PRO କୁ ଅପଗ୍ରେଡ୍ କଲେ ନଗଦ ରିୱାର୍ଡ ଆୟ କରନ୍ତୁ।',
