  'Create your free account using your mobile number or email. It takes less than a minute to get started.': 'ଆପଣଙ୍କ ମୋବାଇଲ୍ ନମ୍ବର ବା ଇମେଲ୍ ବ୍ୟବହାର କରି ମାଗଣା ଆକାଉଣ୍ଟ ତିଆରି କରନ୍ତୁ। ଆରମ୍ଭ କରିବାକୁ ଏକ ମିନିଟ୍‌ରୁ କମ୍ ସମୟ ଲାଗେ।',
