  'Take Practice Quizzes': 'ପ୍ରାକ୍ଟିସ୍ କୁଇଜ୍ ଦିଅନ୍ତୁ',
  'Answer MCQ questions made by experts. Practice PYQ papers, topic-wise quizzes, subject tests and the Daily Challenge to get exam-ready.': 'ବିଶେଷଜ୍ଞଙ୍କ ତିଆରି MCQ ପ୍ରଶ୍ନର ଉତ୍ତର ଦିଅନ୍ତୁ। ପରୀକ୍ଷା ପାଇଁ ପ୍ରସ୍ତୁତ ହେବାକୁ PYQ ପେପର୍, ଟପିକ୍ ଅନୁସାରେ କୁଇଜ୍, ବିଷୟ ଟେଷ୍ଟ ଓ ଦୈନିକ ଚ୍ୟାଲେଞ୍ଜ ଅଭ୍ୟାସ କରନ୍ତୁ।',
  'Track Your Progress': 'ଆପଣଙ୍କ ପ୍ରଗତି ଟ୍ରାକ୍ କରନ୍ତୁ',
  'See how many questions you got right and how fast you answered. Check your leaderboard rank, All India Rank and Exam Readiness Score to improve in every subject.': 'କେତୋଟି ପ୍ରଶ୍ନ ଠିକ୍ ହେଲା ଓ କେତେ ଦ୍ରୁତ ଉତ୍ତର ଦେଲେ ଦେଖନ୍ତୁ। ପ୍ରତ୍ୟେକ ବିଷୟରେ ଉନ୍ନତି କରିବାକୁ ଆପଣଙ୍କ ଲିଡରବୋର୍ଡ ର‍୍ୟାଙ୍କ, ଅଲ୍ ଇଣ୍ଡିଆ ର‍୍ୟାଙ୍କ ଓ ପରୀକ୍ଷା ପ୍ରସ୍ତୁତି ସ୍କୋର୍ ଯାଞ୍ଚ କରନ୍ତୁ।',
  'Invite your friends to AajExam. When a friend upgrades to PRO, you get a cash reward in your account.': 'ଆପଣଙ୍କ ବନ୍ଧୁମାନଙ୍କୁ AajExam କୁ ନିମନ୍ତ୍ରଣ କରନ୍ତୁ। ବନ୍ଧୁ PRO କୁ ଅପଗ୍ରେଡ୍ କଲେ ଆପଣ ଆପଣଙ୍କ ଆକାଉଣ୍ଟରେ ନଗଦ ରିୱାର୍ଡ ପାଆନ୍ତି।',
  'Only Your Knowledge Counts': 'କେବଳ ଆପଣଙ୍କ ଜ୍ଞାନ ହିଁ ଗଣାଯାଏ',
  'You win by knowing more, not by luck. Hard work and study is all that matters.': 'ଆପଣ ଅଧିକ ଜାଣି ଜିତନ୍ତି, ଭାଗ୍ୟରେ ନୁହେଁ। କଠିନ ପରିଶ୍ରମ ଓ ପଢ଼ାପଢ଼ି ହିଁ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ।',
  'Earn With Referrals': 'ରେଫରାଲ୍ ରୁ ଆୟ କରନ୍ତୁ',
  'Invite friends and earn real cash rewards when they upgrade to PRO.': 'ବନ୍ଧୁମାନଙ୍କୁ ନିମନ୍ତ୍ରଣ କରନ୍ତୁ ଓ ସେମାନେ PRO କୁ ଅପଗ୍ରେଡ୍ କଲେ ପ୍ରକୃତ ନଗଦ ରିୱାର୍ଡ ଆୟ କରନ୍ତୁ।',
  'Get Better as You Study': 'ପଢ଼ି ପଢ଼ି ଆହୁରି ଭଲ ହୁଅନ୍ତୁ',
